content:
extends Node

const SETTINGS_PATH := "user://hayat_tounes_settings.json"
const TEMP_PATH := "user://hayat_tounes_settings.tmp"
const BACKUP_PATH := "user://hayat_tounes_settings.backup.json"
const MAX_SETTINGS_BYTES := 64 * 1024
const SCHEMA_VERSION := 1
const DEFAULTS := {
    "master_volume": 0.85,
    "camera_sensitivity": 0.0042,
    "quality_mode": "AUTO"
}

signal master_volume_changed(value: float)
signal camera_sensitivity_changed(value: float)
signal quality_mode_changed(value: String)

var _settings: Dictionary = DEFAULTS.duplicate(true)
var last_error := ""

func _ready() -> void:
    load_settings()
    _apply_master_volume()

func master_volume() -> float:
    return float(_settings.get("master_volume", DEFAULTS["master_volume"]))

func camera_sensitivity() -> float:
    return float(_settings.get("camera_sensitivity", DEFAULTS["camera_sensitivity"]))

func quality_mode() -> String:
    return str(_settings.get("quality_mode", DEFAULTS["quality_mode"]))

func set_master_volume(value: float, persist := true) -> void:
    var clean := clampf(value, 0.0, 1.0)
    _settings["master_volume"] = clean
    _apply_master_volume()
    master_volume_changed.emit(clean)
    if persist:
        save_settings()

func set_camera_sensitivity(value: float, persist := true) -> void:
    var clean := clampf(value, 0.001, 0.02)
    _settings["camera_sensitivity"] = clean
    camera_sensitivity_changed.emit(clean)
    if persist:
        save_settings()

func set_quality_mode(value: String, persist := true) -> void:
    var clean := value.to_upper()
    if clean not in ["AUTO", "LOW", "MEDIUM", "HIGH"]:
        clean = "AUTO"
    _settings["quality_mode"] = clean
    quality_mode_changed.emit(clean)
    if persist:
        save_settings()

func reset_defaults() -> void:
    _settings = DEFAULTS.duplicate(true)
    _apply_master_volume()
    master_volume_changed.emit(master_volume())
    camera_sensitivity_changed.emit(camera_sensitivity())
    quality_mode_changed.emit(quality_mode())
    save_settings()

func load_settings() -> bool:
    last_error = ""
    var primary := _read_settings_file(SETTINGS_PATH)
    if bool(primary.get("ok", false)):
        _settings = _sanitize(primary.get("settings", {}))
        return true

    var backup := _read_settings_file(BACKUP_PATH)
    if bool(backup.get("ok", false)):
        _settings = _sanitize(backup.get("settings", {}))
        last_error = "settings_primary_invalid_recovered_from_backup"
        return true

    _settings = DEFAULTS.duplicate(true)
    if bool(primary.get("exists", false)) or bool(backup.get("exists", false)):
        last_error = "settings_no_valid_copy:primary=%s:backup=%s" % [
            str(primary.get("error", "missing")),
            str(backup.get("error", "missing"))
        ]
        return false
    return true

func save_settings() -> bool:
    last_error = ""
    var payload := {
        "schema_version": SCHEMA_VERSION,
        "master_volume": master_volume(),
        "camera_sensitivity": camera_sensitivity(),
        "quality_mode": quality_mode()
    }
    var encoded := JSON.stringify(payload, "  ")
    if encoded.to_utf8_buffer().size() > MAX_SETTINGS_BYTES:
        last_error = "settings_too_large"
        return false
    if not _write_text_file(TEMP_PATH, encoded):
        last_error = "settings_temp_write_failed"
        return false

    var temp_global := ProjectSettings.globalize_path(TEMP_PATH)
    var settings_global := ProjectSettings.globalize_path(SETTINGS_PATH)
    var backup_global := ProjectSettings.globalize_path(BACKUP_PATH)

    if FileAccess.file_exists(SETTINGS_PATH):
        if FileAccess.file_exists(BACKUP_PATH):
            var remove_old_backup := DirAccess.remove_absolute(backup_global)
            if remove_old_backup != OK:
                _remove_if_exists(TEMP_PATH)
                last_error = "settings_backup_remove_failed:%s" % remove_old_backup
                return false
        var backup_result := DirAccess.copy_absolute(settings_global, backup_global)
        if backup_result != OK:
            _remove_if_exists(TEMP_PATH)
            last_error = "settings_backup_failed:%s" % backup_result
            return false

        var remove_result := DirAccess.remove_absolute(settings_global)
        if remove_result != OK:
            _remove_if_exists(TEMP_PATH)
            last_error = "settings_replace_remove_failed:%s" % remove_result
            return false

    var rename_error := DirAccess.rename_absolute(temp_global, settings_global)
    if rename_error != OK:
        last_error = "settings_replace_rename_failed:%s" % rename_error
        if FileAccess.file_exists(BACKUP_PATH) and not FileAccess.file_exists(SETTINGS_PATH):
            var rollback := DirAccess.copy_absolute(backup_global, settings_global)
            if rollback != OK:
                last_error += ":rollback_failed:%s" % rollback
        _remove_if_exists(TEMP_PATH)
        return false

    # Keep BACKUP_PATH as the pr

evious committed settings. On the first save,
    # seed it from the newly committed primary so recovery is available immediately.
    if not FileAccess.file_exists(BACKUP_PATH):
        var seed_backup := DirAccess.copy_absolute(settings_global, backup_global)
        if seed_backup != OK:
            last_error = "settings_backup_seed_failed:%s" % seed_backup
            return true
    return true

func _read_settings_file(path: String) -> Dictionary:
    if not FileAccess.file_exists(path):
        return {"ok": false, "exists": false, "error": "missing", "settings": {}}
    var file := FileAccess.open(path, FileAccess.READ)
    if file == null:
        return {"ok": false, "exists": true, "error": "settings_open_failed", "settings": {}}
    var length := file.get_length()
    if length < 0 or length > MAX_SETTINGS_BYTES:
        return {"ok": false, "exists": true, "error": "settings_file_too_large", "settings": {}}
    var json := JSON.new()
    if json.parse(file.get_as_text()) != OK:
        return {"ok": false, "exists": true, "error": "invalid_json", "settings": {}}
    var parsed = json.data
    if typeof(parsed) != TYPE_DICTIONARY:
        return {"ok": false, "exists": true, "error": "settings_invalid_json", "settings": {}}
    if int(parsed.get("schema_version", -1)) != SCHEMA_VERSION:
        return {"ok": false, "exists": true, "error": "settings_schema_unsupported", "settings": {}}
    return {"ok": true, "exists": true, "error": "", "settings": parsed}

func _write_text_file(path: String, encoded: String) -> bool:
    var file := FileAccess.open(path, FileAccess.WRITE)
    if file == null:
        return false
    file.store_string(encoded)
    file.flush()
    var ok := file.get_error() == OK
    file.close()
    return ok

func _remove_if_exists(path: String) -> void:
    if FileAccess.file_exists(path):
        DirAccess.remove_absolute(ProjectSettings.globalize_path(path))

func _sanitize(raw: Dictionary) -> Dictionary:
    var result := DEFAULTS.duplicate(true)
    result["master_volume"] = _finite_clamp(raw.get("master_volume", DEFAULTS["master_volume"]), float(DEFAULTS["master_volume"]), 0.0, 1.0)
    result["camera_sensitivity"] = _finite_clamp(raw.get("camera_sensitivity", DEFAULTS["camera_sensitivity"]), float(DEFAULTS["camera_sensitivity"]), 0.001, 0.02)
    var mode := str(raw.get("quality_mode", DEFAULTS["quality_mode"])).to_upper()
    result["quality_mode"] = mode if mode in ["AUTO", "LOW", "MEDIUM", "HIGH"] else "AUTO"
    return result

func _finite_clamp(value, fallback: float, minimum: float, maximum: float) -> float:
    var number := float(value)
    if is_nan(number) or is_inf(number):
        number = fallback
    return clampf(number, minimum, maximum)

func _apply_master_volume() -> void:
    if AudioServer.get_bus_count() <= 0:
        return
    var value := master_volume()
    AudioServer.set_bus_mute(0, value <= 0.0001)
    AudioServer.set_bus_volume_db(0, linear_to_db(maxf(value, 0.0001)))
